function fs_new_content_guides_6a() {
    return [
    [
        'slug'       => 'home-equity-loan-guide',
        'title'      => 'Home Equity Loan: Rates, Limits, and How It Works',
        'keyword'    => 'home equity loan',
        'desc'       => 'A home equity loan explained: how much you can borrow, current rate ranges, closing costs, tax rules, and a worked payment example.',
        'excerpt'    => 'How a home equity loan works, how it differs from a HELOC and a cash-out refinance, how much you can borrow, and whether the interest is tax deductible.',
        'answer'     => 'A home equity loan is a fixed-rate, lump-sum loan secured by your home, typically limited to 80%-85% of your home\'s value minus what you still owe on your mortgage. As of late October 2026, Bankrate reported a national average rate near 8.7%. Interest is tax deductible only if the loan proceeds are used to buy, build, or substantially improve the home securing the loan, per IRS Publication 936.',
        'publish_at' => '2026-11-04 09:00',
        'takeaways'  => [
            'Most lenders cap combined borrowing (your mortgage plus the new loan) at 80%-85% of your home\'s value, though some go to 90% for well-qualified borrowers.',
            'A home equity loan pays out as a single lump sum at a fixed rate; a HELOC is a revolving credit line, usually at a variable rate.',
